INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Latenz immer durch langsames Internet verursacht wird. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Hardware oder Software können Ursachen sein"}, {"text": "Ja", "correct": false, "because": "Zu einseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich die Latenz in einem Netzwerk reduziere?', 3, '[{"text": "Netzwerkoptimierung", "correct": true, "because": "Verringert Verzögerungen"}, {"text": "Schnellere CPU", "correct": false, "because": "Sekundär"}, {"text": "Buntes Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Latenz in IT-Systemen?', 5, '[{"text": "Bandbreite", "correct": true, "because": "Begrenzt Datenfluss"}, {"text": "Signalübertragung", "correct": true, "because": "Verursacht Verzögerung"}, {"text": "Monitorgröße", "correct": false, "because": "Kein Einfluss"}, {"text": "Tastaturtyp", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Latenz wirkt sich auf die Nutzererfahrung aus. b) Sie ist immer vermeidbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Latenz nicht vollständig eliminierbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich die Latenz in einem IT-System analysiere?', 4, '[{"text": "Netzwerkverkehr", "correct": false, "because": "Beeinflusst Latenz"}, {"text": "Hardwareleistung", "correct": false, "because": "Kann Verzögerungen verursachen"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Latenz nur im Netzwerk auftritt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in Hardware oder Software möglich"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich die Latenz in einer Cloud-Anwendung reduziere?', 3, '[{"text": "Bessere Performance", "correct": true, "because": "Verbessert Nutzererfahrung"}, {"text": "Weniger Bandbreite", "correct": false, "because": "Kein direktes Ziel"}, {"text": "Schnellere Installation", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen verringern die Latenz in einem Netzwerk?', 5, '[{"text": "QoS-Einstellungen", "correct": true, "because": "Priorisiert Datenverkehr"}, {"text": "Kürzere Kabel", "correct": true, "because": "Reduziert Übertragungszeit"}, {"text": "Höhere Preise", "correct": false, "because": "Kein technischer Einfluss"}, {"text": "Bunte Router", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Latenz wird in Millisekunden gemessen. b) Sie ist immer konstant. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Latenz schwankt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um die Latenz in einem System zu reduzieren?', 4, '[{"text": "Netzwerkanalyse", "correct": false, "because": "Identifiziert Engpässe"}, {"text": "Optimierte Software", "correct": false, "because": "Verringert Verzögerungen"}, {"text": "Luxusdesign", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Latenz dasselbe wie Bandbreite?', 2, '[{"text": "Nein", "correct": true, "because": "Latenz ist Verzögerung, Bandbreite Kapazität"}, {"text": "Ja", "correct": false, "because": "Verschiedene Konzepte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt eine geringe Latenz in der IT?', 4, '[{"text": "Schnellere Reaktion", "correct": true, "because": "Verbessert Nutzererfahrung"}, {"text": "Echtzeitfähigkeit", "correct": true, "because": "Wichtig für Anwendungen"}, {"text": "Höhere Kosten", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Latenz nur bei Online-Spielen relevant ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch bei Cloud, Streaming etc. wichtig"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um die Latenz in einem WLAN zu messen?', 3, '[{"text": "Ping-Test", "correct": true, "because": "Misst Verzögerung"}, {"text": "Neuer Router", "correct": false, "because": "Kein Messinstrument"}, {"text": "Bunte Kabel", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Latenz beeinflusst Streaming-Qualität. b) Sie hängt nur von Hardware ab.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Netzwerk spielt Rolle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte beeinflussen die Latenz in einer Cloud?', 5, '[{"text": "Serverstandort", "correct": true, "because": "Entfernung erhöht Verzögerung"}, {"text": "Netzwerküberlastung", "correct": true, "because": "Verlangsamt Daten"}, {"text": "Bürogröße", "correct": false, "because": "Kein Einfluss"}, {"text": "Monitorauflösung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich die Latenz in einem System prüfe?', 3, '[{"text": "Datenpaketgröße", "correct": false, "because": "Beeinflusst Verzögerung"}, {"text": "Routing", "correct": false, "because": "Bestimmt Datenweg"}, {"text": "Firmenlogo", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Latenz durch mehr Bandbreite eliminiert werden?', 3, '[{"text": "Nein", "correct": true, "because": "Latenz unabhängig von Kapazität"}, {"text": "Ja", "correct": false, "because": "Bandbreite hilft nur bedingt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Latenz in Echtzeitanwendungen kritisch ist?', 2, '[{"text": "Ja", "correct": true, "because": "Verzögerung stört Ablauf"}, {"text": "Nein", "correct": false, "because": "Kritisch für Reaktionszeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool hilft, Latenz in einem Netzwerk zu reduzieren?', 4, '[{"text": "Load Balancer", "correct": true, "because": "Optimiert Datenfluss"}, {"text": "Neuer Monitor", "correct": false, "because": "Kein Netzwerkfaktor"}, {"text": "Bunte Kabel", "correct": false, "because": "Ästhetisch"}]');
